L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "\232\168\128\227\129\163\227\129\159\227\129\160\227\130\141\227\129\134\227\128\130\230\156\128\229\136\157\227\129\139\227\130\137\227\128\129\227\129\147\227\129\174\228\184\150\231\149\140\232\135\170\228\189\147\227\129\140\229\129\189\231\137\169\227\129\160\227\129\168\227\129\132\227\129\134\227\129\147\227\129\168\227\129\171\230\176\151\227\129\165\227\129\132\227\129\166\227\129\132\227\129\159\227\129\168\227\128\130"
L12_1.m_Talk_ENG = "Didn't I say? I knew this world was a lie from the start."
L12_1.m_Talk_TWN = "\230\136\145\230\178\146\232\170\170\229\151\142\239\188\159\230\136\145\230\137\147\229\190\158\228\184\128\233\150\139\229\167\139\229\176\177\231\159\165\233\129\147\233\128\153\229\128\139\228\184\150\231\149\140\230\152\175\229\129\135\231\154\132\227\128\130"
L12_1.m_Talk_DEU = "Habe ich es dir nicht gesagt? Ich habe von Anfang an gemerkt, dass diese Welt nichts weiter als eine L\195\188ge war."
