L37_1 = "\230\137\128\228\187\165\230\136\145\229\156\168\230\175\143\230\172\161\233\135\141\232\164\135\233\129\142\233\128\153\228\184\128\229\164\169\230\153\130\239\188\140\233\131\189\230\156\131\229\136\187\230\132\143\229\129\154\228\186\155\232\174\138\229\140\150\239\188\140\229\134\141\232\167\128\229\175\159\228\189\160\229\128\145\227\128\130"
L36_1.m_Talk_TWN = L37_1
