L43_1 = "\227\129\130\227\129\130\227\128\130\228\189\149\229\186\166\231\155\174\227\129\139\227\129\174\227\131\171\227\131\188\227\131\151\227\129\167\227\128\140\230\176\151\228\187\152\227\129\141\227\128\141\227\129\174\229\133\134\229\128\153\227\129\140\227\129\130\227\129\163\227\129\159\227\129\139\227\130\137\227\129\170\227\128\130"
L42_1.m_Talk_JPN = L43_1
L43_1 = "Yes. Loop after loop, it seemed like she was experiencing <color=#ffd34c>deja vu</color>."
L42_1.m_Talk_ENG = L43_1
L43_1 = "\230\178\146\233\140\175\239\188\140\229\156\168\229\185\190\230\172\161\231\154\132\233\135\141\232\164\135\228\184\173\239\188\140\229\165\185\228\188\188\228\185\142\230\132\159\232\166\186\229\136\176<color=#ffd34c>\230\151\162\232\166\150\230\132\159</color>\227\128\130"
L42_1.m_Talk_TWN = L43_1
L43_1 = "Ja, es kam mir so vor, als h\195\164tte ich ein <color=#ffd34c>D\195\169j\195\160-vu</color>, als ich die Schleife mehrmals wiederholte."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Oui. \195\128 mesure que la boucle se r\195\169p\195\169tait, Mina a commenc\195\169 \195\160 ressentir une sensation de <color=#ffd34c>d\195\169j\195\160-vu</color>."
