L44_1 = "\227\131\159\227\131\138\227\130\130\229\144\140\227\129\152\227\129\143\227\129\147\227\129\174\231\143\190\232\177\161\227\129\171\229\183\187\227\129\141\232\190\188\227\129\190\227\130\140\227\129\159\232\162\171\229\174\179\232\128\133\227\129\160\227\129\168\228\187\174\229\174\154\227\129\153\227\130\139\227\129\168\227\128\129\n\230\174\139\227\130\138\227\129\1743\228\186\186\227\129\174\228\184\173\227\129\171\227\131\159\227\131\138\227\129\174<color=#ffd34c>\230\156\172\229\189\147\227\129\174\229\143\139\233\129\148</color>\227\129\140\227\129\132\227\130\139\229\143\175\232\131\189\230\128\167\227\130\130\227\129\130\227\130\139\227\129\168\229\136\164\230\150\173\227\129\151\227\129\159\227\128\130"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Assuming that Mina is also a victim here, I figured that she would also have <color=#ffd34c>true friends</color> among the other three people."
L43_1.m_Talk_ENG = L44_1
L44_1 = "\229\129\135\232\168\173\231\177\179\229\168\156\228\185\159\230\152\175\233\128\153\229\128\139\231\143\190\232\177\161\231\154\132\229\143\151\229\174\179\232\128\133\239\188\140\233\130\163\229\133\182\233\164\152\231\154\132\228\184\137\229\128\139\228\186\186\228\185\139\228\184\173\239\188\140\n\230\135\137\232\169\178\228\185\159\230\156\137\231\177\179\229\168\156<color=#ffd34c>\231\156\159\230\173\163\231\154\132\230\156\139\229\143\139</color>\227\128\130"
L43_1.m_Talk_TWN = L44_1
L44_1 = "Unter der Annahme, dass Mina ebenfalls ein Opfer dieses Ph\195\164nomens ist, dachte ich, dass es sich bei den verbleibenden drei Personen um Minas <color=#ffd34c>wahre Freunde</color> handeln m\195\188sste."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Si mon hypoth\195\168se \195\169tait juste, et que Mina s'\195\169tait retrouv\195\169e prise au pi\195\168ge dans un monde qui n'\195\169tait pas le sien, alors il y avait de fortes chances pour que les trois autres soient <color=#ffd34c>ses amis</color>."
