L47_1 = "\227\129\151\227\129\159\227\129\140\227\129\163\227\129\166\227\130\164\227\131\172\227\130\174\227\131\165\227\131\169\227\131\188\227\130\146\229\136\134\229\136\165\227\129\153\227\130\139\227\129\159\227\130\129\227\129\171\227\131\159\227\131\138\227\129\174\232\168\152\230\134\182\227\130\146\229\143\150\227\130\138\230\136\187\227\129\151\227\129\166\227\128\129\n\230\156\172\229\189\147\227\129\174\229\143\139\233\129\148\227\130\146\230\128\157\227\129\132\229\135\186\227\129\155\227\130\139\227\130\136\227\129\134\227\129\170\231\138\182\230\179\129\227\130\146\228\189\156\227\130\139\229\191\133\232\166\129\227\129\140\227\129\130\227\129\163\227\129\159\227\128\130"
L46_1.m_Talk_JPN = L47_1
L47_1 = "So, in order to find the Irregular, I needed Mina to retrieve her lost memories and create situations where she would unconsciously think of her true friends."
L46_1.m_Talk_ENG = L47_1
L47_1 = "\230\137\128\228\187\165\231\130\186\228\186\134\229\136\134\232\190\168\228\184\141\232\166\143\229\190\139\239\188\140\229\176\177\229\191\133\233\160\136\229\137\181\233\128\160\229\135\186\228\184\128\229\128\139\230\131\133\229\162\131\239\188\140\232\174\147\231\177\179\229\168\156\230\129\162\229\190\169\232\168\152\230\134\182\239\188\140\230\131\179\232\181\183\231\156\159\230\173\163\231\154\132\230\156\139\229\143\139\227\128\130"
L46_1.m_Talk_TWN = L47_1
L47_1 = "Um die Irregularit\195\164t zu unterscheiden, war es daher notwendig, Minas Erinnerungen wiederherzustellen und eine Situation zu schaffen, in der sie sich an ihre wahren Freunde erinnern konnte."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Afin d'identifier l'irr\195\169gularit\195\169, je devais d'abord faire en sorte que Mina retrouve ses vrais souvenirs, qui feraient intervenir ses vraies amies. Et me permettrait ainsi d'isoler le coupable."
