L2_1 = "\230\178\146\233\140\175\239\188\140 \230\136\145\230\140\137\231\133\167\233\173\175\232\183\175\228\191\174\231\154\132\232\168\136\231\149\171\230\137\190\229\155\158\232\168\152\230\134\182\229\190\140\239\188\140\229\176\177\229\145\138\232\168\180\228\187\150\232\170\176\230\152\175\230\136\145\231\156\159\230\173\163\231\154\132\230\156\139\229\143\139\227\128\130"
L1_1.m_Talk_TWN = L2_1
L2_1 = "Stimmt, genau wie Lelouch geplant hatte, erz\195\164hlte ich ihm, nachdem ich meine Erinnerungen wiedererlangt hatte, wer meine wahren Freunde sind."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Et gr\195\162ce au plan de Lelouch, j'ai effectivement r\195\169ussi \195\160 me souvenir de l'identit\195\169 de mes v\195\169ritables amies. Et \195\160 la lui indiquer."
L1_1.m_Talk_FRA = L2_1
