L7_1 = "\227\129\167\227\130\130\227\128\129\231\181\144\230\158\156\227\129\140\232\137\175\227\129\143\227\129\170\227\129\139\227\129\163\227\129\159\227\129\139\227\130\137\227\129\163\227\129\166\227\128\129\n\227\129\138\228\186\146\227\129\132\227\129\174\227\129\155\227\129\132\227\129\171\227\129\151\227\129\166\227\130\177\227\131\179\227\130\171\227\129\170\227\130\147\227\129\166\227\129\151\227\129\159\227\129\143\227\129\170\227\129\132\227\128\130"
L6_1.m_Talk_JPN = L7_1
