L8_1 = "\227\129\160\227\129\163\227\129\166\226\128\166\226\128\166\229\173\166\229\156\146\231\165\173\227\129\191\227\129\159\227\129\132\227\129\170\231\137\185\229\136\165\227\129\170\227\130\164\227\131\153\227\131\179\227\131\136\227\129\140\227\129\170\227\129\143\227\129\166\227\130\130\227\128\129\n\231\167\129\227\129\159\227\129\161\227\129\175<color=#ffd34c>\229\133\131\227\129\139\227\130\137\230\156\172\229\189\147\227\129\174\229\143\139\233\129\148\227\129\152\227\130\131\227\129\170\227\129\132\227\128\130\227\129\157\227\129\134\227\129\167\227\129\151\227\130\135\227\128\129\228\188\154\233\149\183\239\188\159\227\128\128\227\131\138\227\130\164\227\130\168\227\131\171\227\130\130\227\128\130</color>"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Because... whether or not it's a special occasion like the school festival, <color=#ffd34c>we're still true friends. Isn't that right, Yen? Naielle?</color>"
L7_1.m_Talk_ENG = L8_1
L8_1 = "\229\155\160\231\130\186\226\128\166\226\128\166\229\176\177\231\174\151\230\178\146\230\156\137\229\173\184\229\156\146\231\165\173\239\188\140<color=#ffd34c>\230\136\145\229\128\145\230\156\172\228\190\134\229\176\177\230\152\175\230\156\139\229\143\139\228\184\141\230\152\175\229\151\142\239\188\159\230\156\131\233\149\183\239\188\159\229\165\136\231\136\190\239\188\159</color>"
L7_1.m_Talk_TWN = L8_1
L8_1 = "Weil ... wir auch an ganz normalen Tagen, wenn keine besondere Veranstaltung wie das Schulfest stattfindet, <color=#ffd34c>wahre Freunde sind. Nicht wahr, Yen? Naielle?</color>"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Apr\195\168s tout... <color=#ffd34c>nous sommes amies, non ? Naielle ? Yen ?</color> Qu'il y ait un gala ou non !"
