L24_1 = "\230\156\172\230\157\165\227\129\170\227\130\137\229\173\152\229\156\168\232\135\170\228\189\147\227\129\140\232\168\177\227\129\149\227\130\140\227\129\170\227\129\132\231\169\186\233\150\147\227\129\167\227\129\153\227\129\140\227\128\1292\227\129\164\227\129\174\228\184\150\231\149\140\227\129\174\230\172\161\229\133\131\231\149\140\233\157\162\227\130\146\n\229\144\140\230\153\130\227\129\171\232\158\141\232\167\163\227\129\149\227\129\155\227\129\166\227\129\151\227\129\190\227\129\134\227\129\187\227\129\169\227\129\174\232\142\171\229\164\167\227\129\170\227\130\168\227\131\141\227\131\171\227\130\174\227\131\188\227\129\171\227\130\136\227\129\163\227\129\166\227\128\129\228\184\128\230\153\130\231\154\132\227\129\171\229\189\162\230\136\144\227\129\149\227\130\140\227\129\159\230\172\161\229\133\131\233\150\147\231\169\186\233\150\147\227\129\167\227\129\153\227\128\130"
L23_1.m_Talk_JPN = L24_1
L24_1 = "It is typically a space that shouldn't exist at all. But, because of the enormous inflow of energy that could fuse the dimension surface of the two worlds, it has been temporarily formed."
L23_1.m_Talk_ENG = L24_1
L24_1 = "\229\142\159\230\156\172\230\152\175\228\184\141\232\169\178\229\173\152\229\156\168\231\154\132\231\169\186\233\150\147\239\188\140\230\152\175\231\148\177\230\150\188\232\182\179\228\187\165\229\144\140\230\153\130\232\158\141\229\140\150\228\186\140\229\128\139\228\184\150\231\149\140\230\172\161\229\133\131\231\149\140\233\157\162\231\154\132\232\131\189\233\135\143\239\188\140\230\137\141\230\154\171\230\153\130\231\148\162\231\148\159\231\154\132\230\172\161\229\133\131\233\150\147\231\169\186\233\150\147\227\128\130"
L23_1.m_Talk_TWN = L24_1
L24_1 = "Urspr\195\188nglich ist es ein Raum, in dem die Existenz selbst nicht erlaubt ist, aber es ist eine Dimensionsoberfl\195\164che, die vor\195\188bergehend aufgrund der Energie gebildet wird, die ausreicht, um gleichzeitig die dimensionale Schnittstelle zwischen den beiden Welten zum Schmelzen zu bringen."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Normalement, aucune existence ne devrait y \195\170tre tol\195\169r\195\169e. Mais gr\195\162ce \195\160 une \195\169nergie capable de fusionner simultan\195\169ment les fronti\195\168res dimensionnelles des deux mondes, un espace interdimensionnel a temporairement pu se former."
