L30_1 = "\234\183\184\235\160\135\236\138\181\235\139\136\235\139\164. \234\183\184\235\166\172\234\179\160 \236\157\180\235\160\135\234\178\140 \235\167\140\235\147\164\236\150\180\236\167\132 \236\176\168\236\155\144\234\176\132 \234\179\181\234\176\132\236\157\128 \234\176\149\235\160\165\237\149\156 \236\160\149\236\139\160\236\152\164\236\151\188 \236\167\128\235\140\128\235\165\188 \237\152\149\236\132\177\237\149\169\235\139\136\235\139\164."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "\227\129\157\227\129\134\227\129\167\227\129\153\227\128\130\227\129\157\227\129\151\227\129\166\227\128\129\227\129\147\227\129\174\227\130\136\227\129\134\227\129\171\227\129\151\227\129\166\228\189\156\227\130\137\227\130\140\227\129\159\230\172\161\229\133\131\233\150\147\231\169\186\233\150\147\227\129\175\227\128\129\n\229\188\183\229\138\155\227\129\170\231\178\190\231\165\158\230\177\154\230\159\147\229\156\176\229\184\175\227\130\146\229\189\162\230\136\144\227\129\151\227\129\190\227\129\153\227\128\130"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Correct. And within the dimensional plain that was formed, a potent mind-polluting zone was created."
L29_1.m_Talk_ENG = L30_1
L30_1 = "\230\178\146\233\140\175\239\188\140\230\150\188\230\152\175\229\166\130\230\173\164\231\148\162\231\148\159\231\154\132\230\172\161\229\133\131\233\150\147\231\169\186\233\150\147\229\189\162\230\136\144\229\188\183\231\131\136\231\154\132\231\178\190\231\165\158\230\177\153\230\159\147\229\156\176\229\184\182\227\128\130"
L29_1.m_Talk_TWN = L30_1
L30_1 = "So ist es. Und der dadurch geschaffene interdimensionale Raum bildet eine \195\188beraus gef\195\164hrliche mentale Kontaminationszone."
L29_1.m_Talk_DEU = L30_1
L30_1 = "En effet. Et cet espace interdimensionnel ainsi cr\195\169\195\169 forme une zone de forte contamination mentale."
