L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "\227\129\167\227\129\153\227\129\174\227\129\167\227\128\129\227\129\147\227\129\147\227\129\170\227\130\137\228\186\186\233\150\147\227\129\174\231\132\161\230\132\143\232\173\152\227\130\146\229\174\159\228\189\147\229\140\150\227\129\151\227\128\129\n\231\143\190\229\174\159\227\129\171\227\129\175\227\129\170\227\129\132\231\144\134\230\131\179\227\129\174\229\164\162\227\129\174\228\184\150\231\149\140\227\130\146\229\133\183\231\143\190\229\140\150\227\129\153\227\130\139\227\129\147\227\129\168\227\129\140\227\129\167\227\129\141\227\129\190\227\129\153\227\128\130"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Therefore, this place can realize the human unconsciousness and create an idealized, dreamlike world."
L30_1.m_Talk_ENG = L31_1
L31_1 = "\229\155\160\230\173\164\229\156\168\233\128\153\229\128\139\231\169\186\233\150\147\232\163\161\239\188\140\229\143\175\228\187\165\229\176\135\228\186\186\233\161\158\231\154\132\230\189\155\230\132\143\232\173\152\n\229\133\183\233\171\148\229\140\150\239\188\140\229\137\181\233\128\160\229\135\186\228\184\128\229\128\139\228\184\141\229\173\152\229\156\168\230\150\188\231\143\190\229\175\166\228\184\173\231\154\132\231\144\134\230\131\179\228\184\150\231\149\140\227\128\130"
L30_1.m_Talk_TWN = L31_1
L31_1 = "Daher kann an diesem Ort das menschliche Unterbewusstsein materialisiert und eine ideale Traumwelt geschaffen werden, die es in der Realit\195\164t nicht gibt."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Il est donc possible de mat\195\169rialiser le subconscient, et d'y cr\195\169er un monde onirique parfait, loin des affres de la r\195\169alit\195\169."
L30_1.m_Talk_FRA = L31_1
