L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "\229\190\133\227\129\163\227\129\166\227\128\129\227\129\130\227\129\170\227\129\159\227\129\175\231\148\159\229\190\146\228\188\154\227\131\161\227\131\179\227\131\144\227\131\188\227\129\167\227\129\175\227\129\170\227\129\132\227\129\174\227\129\171\227\128\129\n\227\129\169\227\129\134\227\130\132\227\129\163\227\129\166\227\130\162\227\131\131\227\130\183\227\131\165\227\131\149\227\130\169\227\131\188\227\131\137\229\173\166\229\156\146\227\130\146\229\174\159\228\189\147\229\140\150\227\129\151\227\129\159\227\129\174\239\188\159"
