L34_1.m_Talk_ENG = L35_1
L35_1 = "\228\184\141\229\176\141\239\188\140\228\189\160\229\143\136\228\184\141\230\152\175\233\152\191\228\187\128\229\188\151\229\190\183\229\173\184\231\148\159\230\156\131\231\154\132\230\136\144\229\147\161\239\188\140\231\130\186\228\187\128\233\186\188\232\166\129\229\176\135\233\152\191\228\187\128\229\188\151\229\190\183\229\173\184\233\153\162\229\133\183\233\171\148\229\140\150\239\188\159"
L34_1.m_Talk_TWN = L35_1
