L37_1 = "\234\184\176\234\179\132\235\138\148 \234\191\136\236\157\132 \234\191\128 \236\136\152 \236\151\134\236\138\181\235\139\136\235\139\164. \235\139\164\236\139\156 \235\167\144\237\149\180, \236\157\180 \234\191\136\236\157\152 \236\132\184\234\179\132\235\165\188 \236\156\160\236\167\128\237\149\152\235\138\148 \235\143\153\235\160\165\236\155\144\236\157\128 \236\152\164\235\161\175\236\157\180 \235\139\185\236\139\160\235\147\164\236\157\152 \235\172\180\236\157\152\236\139\157\236\157\180\236\163\160."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "\230\169\159\230\162\176\227\129\175\229\164\162\227\130\146\232\166\139\227\130\139\227\129\147\227\129\168\227\129\140\227\129\167\227\129\141\227\129\190\227\129\155\227\130\147\227\128\130\n\227\129\164\227\129\190\227\130\138\227\128\129\227\129\147\227\129\174\229\164\162\227\129\174\228\184\150\231\149\140\227\130\146\231\182\173\230\140\129\227\129\151\227\129\166\227\129\132\227\130\139\229\139\149\229\138\155\230\186\144\227\129\175\227\128\129\227\129\130\227\129\170\227\129\159\227\129\159\227\129\161\227\129\174\231\132\161\230\132\143\232\173\152\227\129\167\227\129\153\227\128\130"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Machines do not dream. In other words, your unconsciousness is the only source of this dream world."
L36_1.m_Talk_ENG = L37_1
L37_1 = "\230\169\159\229\153\168\230\152\175\231\132\161\230\179\149\228\189\156\229\164\162\231\154\132\239\188\140\230\136\145\229\134\141\232\170\170\228\184\128\230\172\161\239\188\140\232\131\189\229\164\160\232\174\147\233\128\153\229\128\139\229\164\162\232\163\161\231\154\132\228\184\150\231\149\140\230\140\129\231\186\140\228\184\139\229\142\187\231\154\132\229\139\149\229\138\155\239\188\140\230\152\175\228\190\134\232\135\170\230\150\188\228\189\160\229\128\145\231\154\132\230\189\155\230\132\143\232\173\152\227\128\130"
L36_1.m_Talk_TWN = L37_1
L37_1 = "Maschinen k\195\182nnen nicht tr\195\164umen. Mit anderen Worten: Die einzige Energiequelle, die diese Traumwelt aufrechterh\195\164lt, ist euer Unterbewusstsein."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Les machines ne peuvent pas r\195\170ver. Autrement dit, le moteur permettant de maintenir ce monde actif... n'est autre que votre subconscient."
L36_1.m_Talk_FRA = L37_1
