L38_1 = "\236\160\156 \235\179\184\236\178\180\235\138\148 \235\139\185\236\139\160\235\147\164\236\157\152 \235\172\180\236\157\152\236\139\157\236\157\132 <color=#ffd34c>\236\161\176\236\156\168</color>\237\149\152\235\169\180\236\132\156 \237\149\153\236\155\144\236\160\156\236\157\152 \236\160\132\235\130\160\236\157\132 \236\139\156\235\174\172\235\160\136\236\157\180\236\133\152 \237\149\152\234\179\160 \236\158\136\236\157\132 \235\191\144\236\158\133\235\139\136\235\139\164."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "\229\131\149\227\129\174\230\156\172\228\189\147\227\129\175\227\129\130\227\129\170\227\129\159\227\129\159\227\129\161\227\129\174\231\132\161\230\132\143\232\173\152\227\130\146<color=#ffd34c>\232\170\191\230\149\180</color>\227\129\151\227\129\170\227\129\140\227\130\137\n<color=#ffd34c>\229\173\166\229\156\146\231\165\173\227\129\174\229\137\141\230\151\165</color>\227\130\146\227\130\183\227\131\159\227\131\165\227\131\172\227\131\188\227\130\183\227\131\167\227\131\179\227\129\151\227\129\166\227\129\132\227\129\159\227\129\160\227\129\145\227\129\171\233\129\142\227\129\142\227\129\190\227\129\155\227\130\147\227\128\130"
L37_1.m_Talk_JPN = L38_1
L38_1 = "All my mainframe is doing is <color=#ffd34c>adjusting</color> your unconsciousness and simulating the day before the festival."
L37_1.m_Talk_ENG = L38_1
L38_1 = "\232\128\140\230\136\145\229\143\170\230\152\175<color=#ffd34c>\232\170\191\230\149\180</color>\228\189\160\229\128\145\231\154\132\230\189\155\230\132\143\232\173\152\239\188\140\229\144\140\230\153\130\230\168\161\230\147\172\229\173\184\229\156\146\231\165\173\231\154\132\229\137\141\228\184\128\229\164\169\232\128\140\229\183\178\227\128\130"
L37_1.m_Talk_TWN = L38_1
L38_1 = "Mein Hauptk\195\182rper simuliert nur den Tag vor dem Schulfest und <color=#ffd34c>kontrolliert</color> gleichzeitig euer Unterbewusstsein."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Mon corps n'a plus qu'\195\160 <color=#ffd34c>ajuster</color> le flux de conscience, et \195\160 recr\195\169er une simulation de la veille du gala."
L37_1.m_Talk_FRA = L38_1
