L39_1 = "\237\149\152, \237\149\153\236\155\144\236\160\156\235\157\188\234\179\160? \235\140\128\236\178\180 \236\153\156\234\183\184\235\160\135\234\178\140\234\185\140\236\167\128 \237\149\153\236\155\144\236\160\156\236\151\144 \236\167\145\236\176\169\237\149\152\235\138\148 \234\177\180\235\141\176?"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "\227\129\140\227\128\129\229\173\166\229\156\146\231\165\173\239\188\159\227\128\128\227\129\169\227\129\134\227\129\151\227\129\166\227\129\157\227\130\147\227\129\170\227\129\171\229\173\166\229\156\146\231\165\173\227\129\171\229\159\183\231\157\128\227\129\153\227\130\139\227\129\174\239\188\159"
