L39_1 = "F-festival? But why are you so obsessed with the festival, anyway?"
L38_1.m_Talk_ENG = L39_1
L39_1 = "\228\187\128\233\186\188\239\188\159\229\173\184\229\156\146\231\165\173\239\188\159\228\189\160\231\130\186\228\187\128\233\186\188\232\166\129\233\128\153\233\186\188\229\159\183\232\145\151\230\150\188\229\173\184\229\156\146\231\165\173\239\188\159"
