L40_1 = "\232\179\170\229\149\143\227\129\174\230\132\143\229\155\179\227\129\140\227\130\143\227\129\139\227\130\138\227\129\190\227\129\155\227\130\147\227\129\173\227\128\129\227\131\159\227\131\138\227\129\149\227\130\147\227\128\130"
