L41_1 = "\227\129\147\227\130\140\227\129\175\229\131\149\227\129\174\229\159\183\231\157\128\227\129\167\227\129\175\227\129\130\227\130\138\227\129\190\227\129\155\227\130\147\227\128\130\n\227\129\147\227\130\140\227\129\175\227\129\130\227\129\170\227\129\159\227\129\159\227\129\161\227\129\140\230\156\155\227\130\147\227\129\160\229\164\162\227\129\174\233\155\134\229\144\136\228\189\147\227\129\167\227\129\153\227\128\130"
L40_1.m_Talk_JPN = L41_1
L41_1 = "None of this is my obsession. It is an intersection of all your desires and wishes."
L40_1.m_Talk_ENG = L41_1
L41_1 = "\228\184\141\230\152\175\230\136\145\229\159\183\232\145\151\230\150\188\229\173\184\229\156\146\231\165\173\239\188\140\233\128\153\230\152\175\228\189\160\229\128\145\233\161\152\230\156\155\231\154\132\233\155\134\229\144\136\233\171\148\227\128\130"
