L10_1 = "\227\129\157\227\129\151\227\129\166\229\136\165\227\129\174\232\170\176\227\129\139\227\129\175\226\128\166\226\128\166\227\129\170\227\129\143\227\129\151\227\129\159\229\173\166\231\148\159\230\153\130\228\187\163\227\129\174\227\129\138\227\129\188\227\130\141\227\129\146\227\129\170\232\168\152\230\134\182\227\129\174\227\129\159\227\130\129\227\129\171\227\128\130"
