L11_1 = "\234\176\129\236\158\144 \236\130\172\236\160\149\236\157\128 \235\139\164\235\165\180\236\167\128\235\167\140, \235\170\168\235\145\144\236\157\152 \235\172\180\236\157\152\236\139\157 \237\149\156 \234\181\172\236\132\157\236\151\144\235\138\148 \237\149\153\236\155\144\236\160\156\235\165\188 \235\176\148\235\157\188\234\179\160 \236\158\136\236\151\136\236\150\180\236\154\148."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "\227\129\157\227\130\140\227\129\158\227\130\140\227\129\174\228\186\139\230\131\133\227\129\175\231\149\176\227\129\170\227\130\138\227\129\190\227\129\153\227\129\140\227\128\129\n\227\129\191\227\130\147\227\129\170\231\132\161\230\132\143\232\173\152\227\129\174\231\137\135\233\154\133\227\129\167\229\173\166\229\156\146\231\165\173\227\130\146\230\156\155\227\130\147\227\129\167\227\129\132\227\129\190\227\129\151\227\129\159\227\128\130"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Everyone has their own reason. But you all wanted the festival to happen deep down in your hearts."
L10_1.m_Talk_ENG = L11_1
L11_1 = "\233\155\150\231\132\182\230\131\133\230\179\129\229\144\132\228\184\141\231\155\184\229\144\140\239\188\140\228\189\134\229\164\167\229\174\182\230\189\155\230\132\143\232\173\152\228\184\173\231\154\132\229\133\177\233\128\154\233\187\158\229\176\177\230\152\175\229\173\184\229\156\146\231\165\173\227\128\130"
L10_1.m_Talk_TWN = L11_1
L11_1 = "Die Beweggr\195\188nde m\195\182gen bei jedem Einzelnen von euch zwar anders sein, aber ihr alle hofft im Unterbewusstsein auf das Schulfest."
L10_1.m_Talk_DEU = L11_1
L11_1 = "Chacun d'entre vous projette des d\195\169sirs qui lui sont propres, mais... le d\195\169nominateur commun de vos subconscients, c'est le gala de l'\195\169cole."
L10_1.m_Talk_FRA = L11_1
