L12_1 = "\236\160\132 \235\136\132\234\181\172\235\143\132 \236\139\164\235\167\157\237\149\152\236\167\128 \236\149\138\235\138\148 \237\149\153\236\155\144\236\160\156\235\165\188 \235\167\140\235\147\164\236\150\180\235\130\180\234\184\176 \236\156\132\237\149\152\236\151\172 \234\179\132\236\134\141\237\149\180\236\132\156, \234\179\132\236\134\141\237\149\180\236\132\156\226\128\166\226\128\166 \236\152\164\235\138\152\236\157\132 \235\176\152\235\179\181\237\149\180\236\152\168 \234\178\129\235\139\136\235\139\164."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "\229\131\149\227\129\175\232\170\176\227\130\130\227\130\172\227\131\131\227\130\171\227\131\170\227\129\151\227\129\170\227\129\132\229\173\166\229\156\146\231\165\173\227\130\146\228\189\156\227\130\138\228\184\138\227\129\146\227\130\139\227\129\159\227\130\129\227\129\171\227\129\154\227\129\163\227\129\168\227\128\129\n\227\129\154\227\129\163\227\129\168\226\128\166\226\128\166\228\187\138\230\151\165\227\130\146\231\185\176\227\130\138\232\191\148\227\129\151\227\129\166\227\129\141\227\129\159\227\129\174\227\129\167\227\129\153\227\128\130"
L11_1.m_Talk_JPN = L12_1
L12_1 = "I've been attempting to create a festival that leaves no one disappointed, repeating the same day over and over..."
L11_1.m_Talk_ENG = L12_1
L12_1 = "\230\136\145\231\130\186\228\186\134\229\137\181\233\128\160\229\135\186\228\184\128\229\128\139\232\174\147\230\137\128\230\156\137\228\186\186\233\131\189\230\187\191\230\132\143\231\154\132\229\173\184\229\156\146\231\165\173\239\188\140\230\137\128\228\187\165\230\137\141\228\184\141\230\150\183\229\156\176\226\128\166\226\128\166\233\135\141\232\164\135\228\187\138\229\164\169\227\128\130"
L11_1.m_Talk_TWN = L12_1
L12_1 = "Ich werde weiterhin ein Schulfest gestalten, das niemanden entt\195\164uschen wird ... Deshalb werde ich diesen Tag wiederholen."
L11_1.m_Talk_DEU = L12_1
L12_1 = "Et c'est pour pr\195\169parer un gala qui ne d\195\169cevrait personne... que j'ai recr\195\169\195\169 cette journ\195\169e, encore et encore."
L11_1.m_Talk_FRA = L12_1
