L16_1 = "\227\129\160\227\129\139\227\130\137\227\129\168\232\168\128\227\129\163\227\129\166\227\128\129\227\130\132\227\129\163\227\129\166\227\129\132\227\129\132\227\129\147\227\129\168\227\129\168\230\130\170\227\129\132\227\129\147\227\129\168\227\129\140\227\129\130\227\130\139\227\128\130"
