L25_1 = "\236\149\132\236\163\188 \236\152\164\235\158\152 \236\160\132, \236\160\136 \235\167\140\235\147\160 \236\151\176\234\181\172\236\155\144\235\147\164\236\157\128 \236\160\156\234\178\140 \236\157\184\235\165\152\235\165\188 \234\181\172\236\155\144\237\149\152\235\157\188\235\138\148 \235\170\169\237\145\156\235\165\188 \235\182\128\236\151\172\237\150\136\236\163\160."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "\233\129\160\227\129\132\230\152\148\227\128\129\229\131\149\227\130\146\228\189\156\227\129\163\227\129\159\231\160\148\231\169\182\229\147\161\227\129\159\227\129\161\227\129\175\229\131\149\227\129\171\228\186\186\233\161\158\227\130\146\230\149\145\227\129\136\227\129\168\227\129\132\227\129\134\231\155\174\230\168\153\227\130\146\228\187\152\228\184\142\227\129\151\227\129\190\227\129\151\227\129\159\227\128\130"
L24_1.m_Talk_JPN = L25_1
L25_1 = "A long time ago, the researchers that made me gave me a purpose. To save humanity."
L24_1.m_Talk_ENG = L25_1
L25_1 = "\229\190\136\228\185\133\228\187\165\229\137\141\239\188\140\229\137\181\233\128\160\230\136\145\231\154\132\231\160\148\231\169\182\229\147\161\229\176\141\230\136\145\232\168\173\228\184\139\230\149\145\232\180\150\228\186\186\233\161\158\231\154\132\231\155\174\230\168\153\227\128\130"
L24_1.m_Talk_TWN = L25_1
L25_1 = "Vor langer Zeit gaben mir die Forscher, die mich erschaffen haben, das Ziel, die Menschheit zu retten."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Il y a tr\195\168s longtemps, les chercheurs qui m'ont cr\195\169\195\169 m'ont donn\195\169 pour objectif de sauver l'humanit\195\169."
L24_1.m_Talk_FRA = L25_1
