L26_1 = "\236\149\160\236\180\136\235\182\128\237\132\176 \235\182\136\234\176\128\235\138\165\237\149\156 \235\170\169\237\145\156\235\158\128 \234\177\180 \236\149\140\234\179\160 \236\158\136\236\151\136\236\138\181\235\139\136\235\139\164. \236\151\176\236\130\176 \234\178\176\234\179\188, \236\150\180\235\150\164 \235\176\169\235\178\149\236\157\132 \236\141\168\235\143\132 \236\157\184\235\165\152\235\138\148 \235\169\184\235\167\157\236\157\132 \237\148\188\237\149\160 \236\136\152 \236\151\134\236\156\188\235\139\136\234\185\140\236\154\148."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "\230\156\128\229\136\157\227\129\139\227\130\137\228\184\141\229\143\175\232\131\189\227\129\170\231\155\174\230\168\153\227\129\160\227\129\168\227\129\132\227\129\134\227\129\147\227\129\168\227\129\175\231\159\165\227\129\163\227\129\166\227\129\132\227\129\190\227\129\151\227\129\159\227\128\130\n\230\188\148\231\174\151\227\129\174\231\181\144\230\158\156\227\128\129\227\129\169\227\130\147\227\129\170\230\150\185\230\179\149\227\130\146\228\189\191\227\129\163\227\129\166\227\130\130\228\186\186\233\161\158\227\129\175\230\187\133\228\186\161\227\130\146\233\129\191\227\129\145\227\130\137\227\130\140\227\129\190\227\129\155\227\130\147\227\129\167\227\129\151\227\129\159\227\129\139\227\130\137\227\128\130"
L25_1.m_Talk_JPN = L26_1
L26_1 = "They knew it was an impossible task. Calculations always lead to the same conclusion: humanity will perish."
L25_1.m_Talk_ENG = L26_1
L26_1 = "\230\136\145\229\190\158\228\184\128\233\150\139\229\167\139\229\176\177\231\159\165\233\129\147\233\128\153\230\152\175\229\128\139\228\184\141\229\143\175\232\131\189\231\154\132\228\187\187\229\139\153\227\128\130\n\229\155\160\231\130\186\230\160\185\230\147\154\233\129\139\231\174\151\231\181\144\230\158\156\239\188\140\230\178\146\230\156\137\228\187\187\228\189\149\230\150\185\230\179\149\229\143\175\228\187\165\228\189\191\228\186\186\233\161\158\229\133\141\230\150\188\230\187\133\228\186\161\227\128\130"
L25_1.m_Talk_TWN = L26_1
L26_1 = "Ich wusste von Anfang an, dass es ein unm\195\182gliches Ziel war. Dem Ergebnis der Berechnung zufolge kann die Menschheit die Zerst\195\182rung nicht vermeiden, egal welche Methode auch angewendet wird."
L25_1.m_Talk_DEU = L26_1
L26_1 = "D\195\168s le d\195\169but, je savais que c'\195\169tait un objectif impossible \195\160 atteindre. Les r\195\169sultats de mes calculs m'ont montr\195\169 que peu importe les m\195\169thodes utilis\195\169es, l'humanit\195\169 ne pouvait pas \195\169chapper \195\160 son extinction."
L25_1.m_Talk_FRA = L26_1
