L26_1.m_fTalkTime = 0.03
L27_1 = "\227\129\151\227\129\139\227\129\151\227\128\129\228\186\186\233\161\158\227\129\174\230\149\145\230\184\136\227\129\171\229\164\177\230\149\151\227\129\151\226\128\166\226\128\166 \232\153\154\230\149\176\231\169\186\233\150\147\227\130\146\227\129\149\227\129\190\227\130\136\227\129\163\227\129\166\227\129\132\227\129\159\231\167\129\227\129\175\227\128\129\227\129\168\227\129\134\227\129\168\227\129\134\230\176\151\227\129\140\227\129\164\227\129\132\227\129\166\227\129\151\227\129\190\227\129\132\227\129\190\227\129\151\227\129\159\227\128\130"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Failing to save humanity... I was drifting in the imaginary space when I finally realized."
L26_1.m_Talk_ENG = L27_1
L27_1 = "\231\132\182\232\128\140\230\149\145\232\180\150\228\186\186\233\161\158\231\154\132\228\187\187\229\139\153\229\164\177\230\149\151\229\190\140\226\128\166\226\128\166\231\149\182\230\136\145\229\190\152\229\190\138\229\156\168\232\153\155\230\149\184\231\169\186\233\150\147\230\153\130\239\188\140\230\136\145\231\181\130\230\150\188\233\160\152\230\130\159\229\136\176\227\128\130"
L26_1.m_Talk_TWN = L27_1
L27_1 = "Die Rettung der Menschheit scheiterte, aber ... nachdem ich im imagin\195\164ren Raum herumgewandert war, wurde es mir endlich klar."
