L30_1.m_Talk_TWN = L31_1
L31_1 = "Wenn wir an diesem Ort, der \195\188ber Zeit und Raum herrscht, eine Traumwelt aufbauen, auch wenn die Menschheit nicht gerettet werden kann ... k\195\182nnen wir sie zumindest bewahren!"
