L33_1 = "\230\152\142\230\151\165\227\128\129\228\184\150\231\149\140\227\129\140\230\187\133\228\186\161\227\129\151\227\129\159\227\129\168\227\129\151\227\129\166\227\128\129\n\229\164\137\227\130\143\227\130\137\227\129\170\227\129\1321\230\151\165\227\130\146\231\185\176\227\130\138\232\191\148\227\129\151\227\129\166\228\189\149\227\129\174\230\132\143\229\145\179\227\129\140\227\129\130\227\130\139\227\130\147\227\129\160\239\188\159"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Even if the world were to end tomorrow, what meaning would there be in repeating the same day over and over again?"
L32_1.m_Talk_ENG = L33_1
