L43_1 = "\235\167\158\236\149\132. \235\165\188\235\165\180\236\138\136\236\157\152 \237\158\152\226\128\166\226\128\166 \234\184\176\236\149\132\236\138\164\236\151\144\235\138\148 \236\160\128\237\149\173\237\149\160 \236\136\152 \236\151\134\236\150\180. \236\132\164\235\160\185 \235\179\184\236\157\184\236\157\152 \236\157\152\236\167\128\235\165\188 \234\186\190\235\138\148 \236\157\188\236\157\180\235\157\188\234\179\160 \237\149\180\235\143\132."
