L43_1 = "\227\129\157\227\129\134\227\128\130\227\131\171\227\131\171\227\131\188\227\130\183\227\131\165\227\129\174\227\129\130\227\129\174\229\138\155\226\128\166\226\128\166\227\128\129\227\130\174\227\130\162\227\130\185\227\129\171\227\129\175\232\170\176\227\130\130\233\128\134\227\130\137\227\129\136\227\129\170\227\129\132\227\128\130\n\228\190\139\227\129\136\227\128\129\227\129\157\227\130\140\227\129\140\230\156\172\228\186\186\227\129\174\230\132\143\230\128\157\227\130\146\230\141\187\227\129\152\230\155\178\227\129\146\227\130\139\227\129\147\227\129\168\227\129\160\227\129\163\227\129\159\227\129\168\227\129\151\227\129\166\227\130\130\227\128\130"
